
const WORDS=[{"id": 0, "w": "起源", "p": "qǐyuán", "t": "名词／动词", "m": "nguồn gốc; bắt nguồn", "coll": "起源于、文化起源", "s": "这项研究试图通过考古资料解释这种习俗的起源。"}, {"id": 1, "w": "文献", "p": "wénxiàn", "t": "名词", "m": "tài liệu, tư liệu (có giá trị nghiên cứu)", "coll": "查阅文献、历史文献", "s": "为了了解这幅画的背景，她查阅了大量历史文献。"}, {"id": 2, "w": "凶恶", "p": "xiōng'è", "t": "形容词", "m": "hung ác", "coll": "凶恶的表情、凶恶的敌人", "s": "故事里的怪兽外表十分凶恶，实际上却害怕与人接触。"}, {"id": 3, "w": "揭露", "p": "jiēlù", "t": "动词", "m": "vạch trần, bóc trần", "coll": "揭露真相、揭露问题", "s": "这篇报道揭露了隐藏在交易背后的问题。"}, {"id": 4, "w": "昌盛", "p": "chāngshèng", "t": "形容词", "m": "hưng thịnh, hưng vượng", "coll": "繁荣昌盛、国家昌盛", "s": "这幅年画表达了人们对国家繁荣昌盛的祝愿。"}, {"id": 5, "w": "题材", "p": "tícái", "t": "名词", "m": "đề tài", "coll": "创作题材、传统题材", "s": "这位画家喜欢从普通人的生活中寻找创作题材。"}, {"id": 6, "w": "驱逐", "p": "qūzhú", "t": "动词", "m": "xua đuổi, đuổi", "coll": "驱逐出境、驱逐敌人", "s": "小说中的村民团结起来，驱逐了侵占家园的敌人。"}, {"id": 7, "w": "吉祥", "p": "jíxiáng", "t": "形容词", "m": "may mắn, tốt lành", "coll": "吉祥如意、吉祥的象征", "s": "在这幅画里，这些图案象征着吉祥与幸福。"}, {"id": 8, "w": "里程碑", "p": "lǐchéngbēi", "t": "名词", "m": "mốc lịch sử quan trọng", "coll": "重要里程碑、具有里程碑意义", "s": "这项技术的突破是研究历程中一个重要的里程碑。"}, {"id": 9, "w": "墨水儿", "p": "mòshuǐr", "t": "名词", "m": "mực (để viết)", "coll": "一瓶墨水儿、黑色墨水儿", "s": "书桌上放着一瓶刚买来的墨水儿。"}, {"id": 10, "w": "盖章", "p": "gàizhāng", "t": "动词", "m": "đóng dấu", "coll": "签字盖章、盖章确认", "s": "这份文件需要负责人签字盖章后才能生效。"}, {"id": 11, "w": "联想", "p": "liánxiǎng", "t": "动词", "m": "liên tưởng, nghĩ đến", "coll": "产生联想、联想到故乡", "s": "看到画里的老屋，她立刻联想到了自己的故乡。"}, {"id": 12, "w": "涂抹", "p": "túmǒ", "t": "动词", "m": "tô, quét lên, bôi lên", "coll": "涂抹颜料、均匀涂抹", "s": "画家在木板上均匀地涂抹颜料，准备进行下一步印制。"}, {"id": 13, "w": "终究", "p": "zhōngjiū", "t": "副词", "m": "chung quy, xét cho cùng, cuối cùng", "coll": "终究会明白、终究没能", "s": "虽然他一再修改计划，这次展览终究没能如期举行。"}, {"id": 14, "w": "烟花爆竹", "p": "yānhuā bàozhú", "t": "名词", "m": "pháo hoa và pháo nổ", "coll": "燃放烟花爆竹、烟花爆竹的声音", "s": "春节期间，村里不时传来烟花爆竹的声音。"}, {"id": 15, "w": "寄托", "p": "jìtuō", "t": "动词", "m": "gửi gắm", "coll": "寄托希望、寄托情感", "s": "这些传统图案寄托着人们对美好生活的向往。"}, {"id": 16, "w": "增添", "p": "zēngtiān", "t": "动词", "m": "tăng thêm, thêm", "coll": "增添色彩、增添乐趣", "s": "几盆鲜花为朴素的房间增添了几分生气。"}, {"id": 17, "w": "丰收", "p": "fēngshōu", "t": "名词／动词", "m": "vụ mùa bội thu; được mùa", "coll": "获得丰收、丰收的喜悦", "s": "今年风调雨顺，村里的庄稼获得了丰收。"}, {"id": 18, "w": "发财", "p": "fā cái", "t": "动词", "m": "phát tài, kiếm được nhiều tiền", "coll": "发财致富、恭喜发财", "s": "春节拜年时，人们常互相祝福恭喜发财。"}, {"id": 19, "w": "连年", "p": "liánnián", "t": "副词", "m": "liên tiếp nhiều năm, năm này qua năm khác", "coll": "连年增长、连年丰收", "s": "随着产品质量提高，这家企业的销量连年增长。"}, {"id": 20, "w": "寓言", "p": "yùyán", "t": "名词", "m": "truyện ngụ ngôn", "coll": "寓言故事、一则寓言", "s": "老师通过一则简单的寓言说明了合作的重要性。"}, {"id": 21, "w": "信仰", "p": "xìnyǎng", "t": "名词", "m": "tín ngưỡng", "coll": "宗教信仰、坚定信仰", "s": "我们应该尊重不同文化背景的人各自的信仰。"}, {"id": 22, "w": "喜闻乐见", "p": "xǐwén lèjiàn", "t": "成语", "m": "ưa nghe thích xem, được mọi người yêu thích", "coll": "群众喜闻乐见、喜闻乐见的形式", "s": "节目采用了群众喜闻乐见的形式，吸引了许多观众。"}, {"id": 23, "w": "神气", "p": "shénqì", "t": "形容词", "m": "oai vệ, uy nghi", "coll": "神气十足、显得神气", "s": "小男孩穿上新制服，显得格外神气。"}, {"id": 24, "w": "翘", "p": "qiào", "t": "动词", "m": "vênh, vểnh", "coll": "嘴角翘起来、翘着腿", "s": "听到夸奖，她的嘴角不由得翘了起来。"}, {"id": 25, "w": "神态", "p": "shéntài", "t": "名词", "m": "thần thái, dáng vẻ, bộ dạng", "coll": "神态自然、人物神态", "s": "这幅肖像画细腻地表现了人物的神态。"}, {"id": 26, "w": "盛开", "p": "shèngkāi", "t": "动词", "m": "nở rộ, đua nở", "coll": "鲜花盛开、盛开的花朵", "s": "春天到了，公园里的鲜花竞相盛开。"}, {"id": 27, "w": "散发", "p": "sànfā", "t": "动词", "m": "tỏa ra, phát ra", "coll": "散发香气、散发光芒", "s": "刚出炉的面包散发着诱人的香气。"}, {"id": 28, "w": "耸", "p": "sǒng", "t": "动词", "m": "nhún (vai)", "coll": "耸肩、耸立", "s": "面对这个问题，他只是耸了耸肩，没有回答。"}, {"id": 29, "w": "州", "p": "zhōu", "t": "名词", "m": "châu (đơn vị hành chính thời xưa)", "coll": "古代的州、州郡制度", "s": "老师在地图上标出了古代几个州的位置。"}, {"id": 30, "w": "外行", "p": "wàiháng", "t": "名词／形容词", "m": "người ngoài nghề; không am hiểu chuyên môn", "coll": "完全外行、外行人", "s": "在陶瓷鉴定方面，我完全是个外行，还需要向专家请教。"}, {"id": 31, "w": "推销", "p": "tuīxiāo", "t": "动词", "m": "chào hàng, đẩy mạnh tiêu thụ", "coll": "推销产品、上门推销", "s": "他不只是向顾客推销产品，也会耐心介绍使用方法。"}, {"id": 32, "w": "吞吞吐吐", "p": "tūntūntǔtǔ", "t": "成语", "m": "ngập ngừng ấp úng", "coll": "说话吞吞吐吐、吞吞吐吐地回答", "s": "一问到迟到的原因，他就吞吞吐吐，半天也说不清楚。"}, {"id": 33, "w": "残次品", "p": "cáncìpǐn", "t": "名词", "m": "hàng lỗi, hàng bị hư hỏng hoặc kém phẩm chất", "coll": "处理残次品、残次品回收", "s": "质检人员把有缺陷的残次品单独放在一边，等待处理。"}, {"id": 34, "w": "次品", "p": "cìpǐn", "t": "名词", "m": "hàng loại hai, hàng lỗi", "coll": "检出次品、次品率", "s": "工厂加强了质量管理，次品的数量明显减少。"}, {"id": 35, "w": "现成", "p": "xiànchéng", "t": "形容词", "m": "làm sẵn, có sẵn", "coll": "现成的材料、现成的办法", "s": "这个问题没有现成的答案，需要我们自己探索。"}, {"id": 36, "w": "谢绝", "p": "xièjué", "t": "动词", "m": "từ chối khéo", "coll": "谢绝参观、谢绝礼品", "s": "展厅正在维修，暂时谢绝参观。"}, {"id": 37, "w": "故乡", "p": "gùxiāng", "t": "名词", "m": "quê hương, quê nhà", "coll": "思念故乡、回到故乡", "s": "无论走到哪里，她都忘不了故乡熟悉的味道。"}, {"id": 38, "w": "扎实", "p": "zhāshi", "t": "形容词", "m": "vững chắc, chắc chắn", "coll": "基础扎实、工作扎实", "s": "只有打下扎实的基础，才能进一步提高创作水平。"}, {"id": 39, "w": "塑造", "p": "sùzào", "t": "动词", "m": "đắp nặn, xây dựng (hình tượng nghệ thuật)", "coll": "塑造形象、塑造人物", "s": "这位作家通过生活细节塑造了鲜活的人物形象。"}, {"id": 40, "w": "手法", "p": "shǒufǎ", "t": "名词", "m": "thủ pháp, kỹ năng, kỹ xảo", "coll": "表现手法、创作手法", "s": "这幅画运用独特的表现手法，展现了乡村节日的热闹气氛。"}, {"id": 41, "w": "派别", "p": "pàibié", "t": "名词", "m": "phe phái, trường phái", "coll": "不同派别、艺术派别", "s": "这本书介绍了几个主要艺术派别各自的特点。"}, {"id": 42, "w": "借鉴", "p": "jièjiàn", "t": "动词", "m": "lấy làm gương, dùng để tham khảo", "coll": "借鉴经验、值得借鉴", "s": "设计新课程时，我们可以借鉴其他学校的成功经验。"}, {"id": 43, "w": "再接再厉", "p": "zàijiē zàilì", "t": "成语", "m": "không ngừng cố gắng", "coll": "再接再厉、希望再接再厉", "s": "这次比赛取得了好成绩，老师鼓励大家再接再厉。"}, {"id": 44, "w": "心得", "p": "xīndé", "t": "名词", "m": "điều tâm đắc, kinh nghiệm và nhận thức rút ra", "coll": "学习心得、交流心得", "s": "培训结束后，大家围坐在一起交流学习心得。"}, {"id": 45, "w": "缺席", "p": "quē xí", "t": "动词", "m": "vắng (họp), nghỉ học", "coll": "因故缺席、缺席会议", "s": "如果因故缺席会议，请提前向负责人说明情况。"}, {"id": 46, "w": "劲头", "p": "jìntou", "t": "名词", "m": "tinh thần hăng hái, sức lực, đà nỗ lực", "coll": "劲头十足、学习劲头", "s": "虽然已经工作了一整天，他学习新技术的劲头依然很足。"}, {"id": 47, "w": "占据", "p": "zhànjù", "t": "动词", "m": "chiếm, chiếm giữ", "coll": "占据位置、占据市场", "s": "这家公司凭借可靠的产品，逐渐占据了更多市场份额。"}, {"id": 48, "w": "确立", "p": "quèlì", "t": "动词", "m": "xác lập, thiết lập", "coll": "确立目标、确立原则", "s": "经过讨论，团队终于确立了下一阶段的目标。"}, {"id": 49, "w": "信念", "p": "xìnniàn", "t": "名词", "m": "niềm tin, lòng tin", "coll": "坚定信念、共同信念", "s": "即使遇到挫折，她也始终坚持自己的信念。"}, {"id": 50, "w": "任重道远", "p": "rènzhòng dàoyuǎn", "t": "成语", "m": "gánh vác nhiệm vụ nặng nề trên con đường dài", "coll": "任重道远、深感任重道远", "s": "保护传统文化任重道远，需要几代人共同努力。"}, {"id": 51, "w": "一帆风顺", "p": "yīfān fēngshùn", "t": "成语", "m": "thuận buồm xuôi gió, mọi việc suôn sẻ", "coll": "祝你一帆风顺、并非一帆风顺", "s": "创业的道路并非一帆风顺，但他始终没有放弃。"}];
